'use strict';
(()=>{const form=document.querySelector('.blog-search');if(!form)return;const input=form.querySelector('input'),grid=document.querySelector('.blog-grid'),pages=document.querySelector('.blog-pagination'),status=document.querySelector('.blog-results');const original=grid.innerHTML;let data=null,version=0;
function card(a){const article=document.createElement('article');article.className='blog-card';const link=document.createElement('a');link.href=a.url||'/blog/'+a.slug+'/';if(a.image){const img=document.createElement('img');img.src=a.image;img.alt=a.title;img.width=1000;img.height=649;img.loading='lazy';link.append(img);}const title=document.createElement('h2');title.textContent=a.title;link.append(title);if(!a.image){const p=document.createElement('p');p.textContent=a.description;link.append(p);}article.append(link);return article;}
async function search(){const current=++version,term=input.value.trim();if(!term){grid.innerHTML=original;pages.hidden=false;status.hidden=true;history.replaceState(null,'',location.pathname);return;}status.hidden=false;status.textContent='Searching…';try{if(!data){const response=await fetch('/assets/blog-index.json');if(!response.ok)throw Error();data=await response.json();}if(current!==version)return;const words=term.toLowerCase().split(/\s+/);const found=data.filter(a=>words.every(w=>(a.title+' '+a.description).toLowerCase().includes(w)));grid.replaceChildren(...found.map(card));pages.hidden=true;status.textContent=found.length+' article'+(found.length===1?'':'s')+' found for “'+term+'”. ';const reset=document.createElement('a');reset.href=location.pathname;reset.textContent='Clear search';status.append(reset);history.replaceState(null,'',location.pathname+'?q='+encodeURIComponent(term));}catch{if(current!==version)return;status.textContent='Search is temporarily unavailable. Please browse the articles below.';pages.hidden=false;grid.innerHTML=original;}}
form.addEventListener('submit',e=>{e.preventDefault();search();});const q=new URLSearchParams(location.search).get('q');if(q){input.value=q;search();}
})();
